import { Component, Element, Prop, State, h } from '@stencil/core';

@Component({
  tag: 'std-collapse-total',
  styleUrl: 'std-collapse-total.css',
  shadow: true
})
export class StdCollapseTotalComponent {
  @Prop() label: string;
  @Prop() numberCounts: string;
  @Prop() total: string;

  @State() isOpen: boolean;

  @Element() el: HTMLElement;

  toggleCollapse(): void {
    this.isOpen = !this.isOpen;

    // const body = this.el.shadowRoot.querySelector('.css-collapse-body') as HTMLElement;
    // body.style.maxHeight = this.isOpen ? `${body.scrollHeight}px` : '0px';
  }

  render() {
    const isNegative = this.total?.startsWith('-');

    return (
      <div class={`css-collapse rounded-lg border border-alternative-medium bg-white ${this.isOpen ? 'is-open' : ''}`}>
        <div class="css-collapse-header h-14 p-4 lg:pr-16 flex items-center justify-between" onClick={() => this.toggleCollapse()}>
          <div class="flex items-center gap-2">
            <i class={`icon-chevron-down transform transition-transform duration-300 ${this.isOpen ? 'rotate-180' : ''} text-2xl leading-none text-dark`}></i>
            <p class="font-bold text-dark whitespace-nowrap">{this.label}</p>
          </div>
          <div class="flex items-end lg:items-center lg:gap-2 justify-end flex-col-reverse lg:flex-row">
            <p class="text-dark text-sm lg:min-w-12">{this.numberCounts}</p>
            <p class={`font-bold text-sm lg:min-w-[130px] text-right ${isNegative ? 'text-error' : ''}`}>
              {this.total}
            </p>
          </div>
        </div>
        {/* transition-all duration-500 ease-in-out */}
        <div class={`css-collapse-body hidden`}>
          <slot />
        </div>
      </div>
    );
  }
}
